/** Run one CLI invocation end to end: parse flags, resolve the release context
 * from git, load items, generate, then write or compare. */
async function main(args: string[] = process.argv.slice(2)): Promise<void> {
  const options = parseArgs(args);
  applyReleaseContext(options);
  const items = await loadItems(options);
  const outputPath = resolve(options.output);
  const generationOptions = buildGenerationOptions(options, items);
  const selectionReport = options.explain ? explainChangelogSelection(generationOptions) : undefined;

  // OPT-IN (`--format json` without `--summary`): alias for the structured
  // `--changelog-json` document, giving agents a single standard `--format`
  // flag for machine-readable output. `--summary --format json` is handled
  // separately below, and `--suggest-semver` keeps its dedicated JSON shape
  // (the semver analysis) instead of being aliased to the full document.
  if (options.format === "json" && !options.summary && !options.changelogJson && !options.suggestSemver) {
    options.changelogJson = true;
  }

  // OPT-IN (`--summary`): compact one-line-per-change output for quick agent
  // scanning. Emits flat entries (release heading + category + item) instead
  // of full markdown. `--format json` switches to a JSON array; the default
  // `--format md` renders bracketed text lines (`[version] category: title (id)`).
  // Never writes a file.
  if (options.summary) {
    const entries = createChangelogSummary(generationOptions);
    if (options.format === "json") {
      const payload = {
        entries,
        format: "json",
        item_count: entries.length,
        ...(selectionReport ? { selection_report: selectionReport } : {}),
      };
      process.stdout.write(JSON.stringify(payload, null, 2) + "\n");
    } else {
      for (const entry of entries) {
        process.stdout.write(formatSummaryLine(entry) + "\n");
      }
      if (selectionReport) writeSelectionReport(selectionReport);
    }
    return;
  }

  // OPT-IN (`--changelog-json`): emit the full structured changelog document to
  // stdout and exit, leaving every other mode and CHANGELOG.md untouched.
  if (options.changelogJson) {
    const document = buildChangelogDocument(generationOptions);
    const payload = selectionReport
      ? { ...document, selection_report: selectionReport }
      : document;
    process.stdout.write(JSON.stringify(payload, null, 2) + "\n");
    return;
  }

  // OPT-IN (`--suggest-semver`) without `--changelog-json`: emit only the
  // semver analysis as JSON to stdout and exit. Never writes CHANGELOG.md and
  // never touches default markdown.
  if (options.suggestSemver) {
    const suggestion = suggestSemver(generationOptions);
    const payload = selectionReport
      ? { ...suggestion, selection_report: selectionReport }
      : suggestion;
    process.stdout.write(JSON.stringify(payload, null, 2) + "\n");
    return;
  }

  if (!options.stdout) {
    const result = writeChangelog({
      ...generationOptions,
      output: outputPath,
      mode: options.mode,
      check: options.check,
    });
    const summary = buildSummary(options, result, outputPath, selectionReport);

    if (options.githubOutput) writeGitHubOutput(summary);
    if (options.githubStepSummary) writeGitHubStepSummary(result.markdown);
    if (options.json) {
      process.stdout.write(JSON.stringify(summary) + "\n");
    } else if (options.check) {
      console.error(result.changed ? `Changelog is out of date: ${outputPath}` : `Changelog is up to date: ${outputPath}`);
    } else {
      console.error(`Wrote ${outputPath}`);
    }
    if (!options.json && selectionReport) {
      writeSelectionReport(selectionReport);
    }

    if (options.check && result.changed) {
      if (options.checkDiff) writeCheckDiff(options, outputPath, result.markdown);
      // Set the status and return rather than `process.exit(1)`: Node may still
      // have the diff queued when stderr is a pipe (exactly the CI case this
      // diff exists for), and `process.exit` abandons pending stdio writes. The
      // failure message would then be truncated precisely where it is needed.
      process.exitCode = 1;
      return;
    }
    return;
  }

  const generated = createChangelog(generationOptions);
  const existing = options.mode === "prepend" && existsSync(outputPath)
    ? readFileSync(outputPath, "utf-8")
    : undefined;
  const merged = options.mode === "prepend"
    ? mergeChangelog(existing, generated.markdown, { title: options.title })
    : { markdown: generated.markdown, action: "replaced" as const, changed: true };

  if (options.stdout) {
    if (options.json) {
      const summary = buildSummary(options, {
        output: outputPath,
        markdown: merged.markdown,
        action: merged.action,
        changed: merged.changed,
        itemCount: generated.itemCount,
        bytes: Buffer.byteLength(merged.markdown, "utf-8"),
      }, outputPath, selectionReport);
      if (options.githubOutput) writeGitHubOutput(summary);
      if (options.githubStepSummary) writeGitHubStepSummary(merged.markdown);
      process.stdout.write(JSON.stringify(summary) + "\n");
      return;
    }
    if (selectionReport) {
      writeSelectionReport(selectionReport);
    }
    if (options.githubStepSummary) writeGitHubStepSummary(merged.markdown);
    process.stdout.write(merged.markdown);
    return;
  }

}

/** Turn argv into validated options, rejecting an unknown flag with a
 * near-miss suggestion rather than ignoring it - a silently dropped flag would
 * generate a subtly different changelog and still exit zero. */
function parseArgs(args: string[]): CliOptions {
  const normalizedArgs = normalizeArgs(args);
  const options: CliOptions = {
    output: "CHANGELOG.md",
    stdout: false,
    json: false,
    stdin: false,
    pmArgs: [],
    groupBy: "version",
    sectionBy: "category",
    summary: false,
    format: "md",
    conventional: false,
    contributors: false,
    breakingChanges: false,
    suggestSemver: false,
    emojiPrefix: false,
    includeMetadata: false,
    changelogJson: false,
    includeEmpty: false,
    includeLinks: false,
    mode: "replace",
    check: false,
    checkDiff: true,
    explain: false,
    githubOutput: false,
    githubStepSummary: false,
    versionFromPackage: false,
    dateFromVersion: false,
    sincePreviousTag: false,
    untilReleaseTag: false,
    allReleaseTags: false,
    releaseTagPattern: "v*",
    pendingRelease: true,
    respectItemRelease: false,
    excludeTags: [],
  };

  for (let i = 0; i < normalizedArgs.length; i++) {
    const rawArg = normalizedArgs[i];
    const arg = resolveOptionAlias(rawArg);
    switch (arg) {
      case "--help":
      case "-h":
        printHelp();
        process.exit(0);
      case "--output":
      case "-o":
        options.output = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--stdout":
        options.stdout = true;
        break;
      case "--json":
        options.json = true;
        break;
      case "--check":
        options.check = true;
        break;
      case "--no-check-diff":
        options.checkDiff = false;
        break;
      case "--explain":
        options.explain = true;
        break;
      case "--github-output":
      case "--set-output":
        options.githubOutput = true;
        break;
      case "--github-step-summary":
        options.githubStepSummary = true;
        break;
      case "--input":
      case "-i":
        options.input = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--stdin":
        options.stdin = true;
        break;
      case "--pm-root":
        options.pmRoot = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--pm-bin":
        options.pmBin = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--pm-arg":
        options.pmArgs.push(requireAnyValue(normalizedArgs, ++i, rawArg));
        break;
      case "--pm-cwd":
        options.pmCwd = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--title":
        options.title = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--version":
        options.version = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--release-version-from-package":
        options.versionFromPackage = true;
        break;
      case "--date":
        options.date = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--date-fallback":
        options.dateFallback = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--date-from-version":
        options.dateFromVersion = true;
        break;
      case "--since":
        options.since = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--since-previous-tag":
        options.sincePreviousTag = true;
        break;
      case "--until":
        options.until = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--until-release-tag":
        options.untilReleaseTag = true;
        break;
      case "--all-release-tags":
        options.allReleaseTags = true;
        break;
      case "--release-tag-pattern":
        options.releaseTagPattern = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--no-pending-release":
        options.pendingRelease = false;
        break;
      case "--status":
      case "--statuses":
        options.statuses = requireValue(normalizedArgs, ++i, rawArg)
          .split(",")
          .map((status) => status.trim())
          .filter(Boolean);
        break;
      case "--group-by":
        options.groupBy = parseGroupBy(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--section-by":
        options.sectionBy = parseSectionBy(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--summary":
        options.summary = true;
        break;
      case "--format":
        options.format = parseFormat(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--conventional":
        options.conventional = true;
        break;
      case "--contributors":
        options.contributors = true;
        break;
      case "--breaking-changes":
        options.breakingChanges = true;
        break;
      case "--suggest-semver":
        options.suggestSemver = true;
        break;
      case "--body-preview":
        options.bodyPreview = parseBodyPreview(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--emoji-prefix":
        options.emojiPrefix = true;
        break;
      case "--include-metadata":
        options.includeMetadata = true;
        break;
      case "--changelog-json":
        options.changelogJson = true;
        break;
      case "--limit":
        options.limit = parseLimit(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--since-version":
        options.sinceVersion = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--mode":
        options.mode = parseMode(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--include-empty":
        options.includeEmpty = true;
        break;
      case "--include-links":
        options.includeLinks = true;
        break;
      case "--no-links":
        options.includeLinks = false;
        break;
      case "--item-url-base":
        options.itemUrlBase = requireValue(normalizedArgs, ++i, rawArg);
        break;
      case "--item-ref-style":
        options.itemRefStyle = parseItemRefStyle(requireValue(normalizedArgs, ++i, rawArg));
        break;
      case "--respect-item-release":
        options.respectItemRelease = true;
        break;
      // Repeatable and comma-separated forms both accumulate, mirroring
      // --status/--statuses, so agents can pass either shape.
      case "--exclude-tag":
      case "--exclude-tags":
        options.excludeTags.push(
          ...requireValue(normalizedArgs, ++i, rawArg)
            .split(",")
            .map((tag) => tag.trim())
            .filter(Boolean)
        );
        break;
      default:
        throw unknownOptionError(rawArg);
    }
  }

  return options;
}

/** Split `--flag=value` into separate tokens so both spellings reach one
 * parsing path. */
function normalizeArgs(args: string[]): string[] {
  const normalized: string[] = [];
  for (const arg of args) {
    const equalsIndex = arg.indexOf("=");
    if (equalsIndex <= 0) {
      normalized.push(arg);
      continue;
    }
    const flag = arg.slice(0, equalsIndex);
    if (!VALUE_OPTIONS.has(flag)) {
      normalized.push(arg);
      continue;
    }
    normalized.push(flag, arg.slice(equalsIndex + 1));
  }
  return normalized;
}

function resolveOptionAlias(arg: string): string {
  return OPTION_ALIASES[arg] ?? arg;
}

/** Build the rejection for an unrecognized flag, with a spelling suggestion when
 * one is close enough to be worth offering. The raw `arg` is echoed rather than
 * the normalized token so the message quotes what the caller actually typed,
 * including any `=value` suffix — a user who wrote `--modes=prepend` needs to see
 * that spelling to spot the error. */
function unknownOptionError(arg: string): Error {
  const token = optionToken(arg);
  const suggestion = suggestOption(token);
  const hint = suggestion ? ` Did you mean '${suggestion}'?` : "";
  return new Error(`Unknown option: ${arg}.${hint} Run --help for usage.`);
}

function optionToken(arg: string): string {
  if (!arg.startsWith("-")) return arg;
  const equalsIndex = arg.indexOf("=");
  return equalsIndex > 0 ? arg.slice(0, equalsIndex) : arg;
}

/** Find the closest known flag to a mistyped one, or `undefined` when nothing
 * is close enough to be worth suggesting. Ties break toward the shorter name so
 * the suggestion is the more common flag. */
function suggestOption(arg: string, knownOptions: readonly string[] = KNOWN_OPTIONS): string | undefined {
  let best: { option: string; distance: number } | undefined;
  for (const candidate of knownOptions) {
    const distance = editDistance(arg, candidate);
    // Keep suggestions conservative: close edits only.
    const threshold = Math.max(2, Math.floor(candidate.length * 0.34));
    if (distance > threshold) continue;
    if (!best || distance < best.distance) {
      best = { option: candidate, distance };
      continue;
    }
    if (distance === best.distance && candidate.length < best.option.length) {
      best = { option: candidate, distance };
    }
  }
  return best?.option;
}

/** Levenshtein distance between two strings, used only to rank flag
 * suggestions. */
function editDistance(left: string, right: string): number {
  if (left === right) return 0;
  const rows = left.length + 1;
  const cols = right.length + 1;
  const matrix = Array.from({ length: rows }, () => new Array<number>(cols).fill(0));
  for (let i = 0; i < rows; i++) matrix[i][0] = i;
  for (let j = 0; j < cols; j++) matrix[0][j] = j;
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      const substitutionCost = left[i - 1] === right[j - 1] ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + substitutionCost
      );
    }
  }
  return matrix[rows - 1][cols - 1];
}

/** Fill version, date, and time bounds from the checkout, mutating `options` in
 * place. The version may come from the nearest package.json; the dates and
 * bounds come from git tags. Explicit flags are preserved; only gaps filled. */
function applyReleaseContext(options: CliOptions): void {
  if (options.allReleaseTags) {
    const cwd = options.pmCwd ? resolve(options.pmCwd) : process.cwd();
    const context = resolveReleaseContext({
      cwd,
      version: options.version,
      versionFromPackage: options.versionFromPackage,
      dateFallback: options.dateFallback,
      dateFromVersion: options.dateFromVersion,
    });
    options.version = context.version;
    const resolution = resolveReleaseTagWindowResolution({
      cwd,
      tagPattern: options.releaseTagPattern,
      includeOrphaned: true,
      pendingVersion: options.version,
      pendingTimestamp: options.until ?? options.date ?? context.date,
      pendingRelease: options.pendingRelease,
    });
    // An empty resolution here means the repository has no tag history at
    // all (zero tags, nothing to resolve a version from), which the CLI and
    // extension spell as absent history so the generator keeps its
    // single-section `## Unreleased` fallback for pre-first-release repos;
    // deliberate emptiness (a suppressed pending release with no Unreleased
    // window) is a library-only shape this surface never requests. The
    // suppressed pending release is forwarded so items declaring that version
    // land under `Unreleased` instead of an older real release.
    const { releaseWindows, suppressedPendingRelease } = resolveGenerationReleaseWindows(resolution);
    options.releaseWindows = releaseWindows;
    options.suppressedPendingRelease = suppressedPendingRelease;
    return;
  }

  if (
    !options.version
    && !options.versionFromPackage
    && !options.dateFallback
    && !options.dateFromVersion
    && !options.sincePreviousTag
    && !options.untilReleaseTag
  ) return;
  const context = resolveReleaseContext({
    cwd: options.pmCwd ? resolve(options.pmCwd) : process.cwd(),
    version: options.version,
    versionFromPackage: options.versionFromPackage,
    dateFallback: options.dateFallback,
    dateFromVersion: options.dateFromVersion,
    since: options.since,
    sincePreviousTag: options.sincePreviousTag,
    until: options.until,
    untilReleaseTag: options.untilReleaseTag,
  });
  options.version = context.version;
  options.date = options.date ?? context.date;
  options.since = context.since;
  options.until = context.until;
}

/** Load pm items from stdin, a JSON file, or the real pm CLI, in that order of
 * precedence. Bodies are requested only when a preview will render them, since
 * they make the list payload substantially larger. */
async function loadItems(options: CliOptions, input: Readable = stdin): Promise<PmItem[]> {
  if (options.stdin) {
    return parsePmItemsJson(await readStdin(input));
  }

  if (options.input) {
    return parsePmItemsJson(readFileSync(resolve(options.input), "utf-8"));
  }

  return readPmItems({
    pmRoot: options.pmRoot,
    pmBin: options.pmBin,
    pmArgs: options.pmArgs,
    cwd: options.pmCwd ? resolve(options.pmCwd) : undefined,
    // Only request bodies when --body-preview needs them; otherwise keep the
    // lighter default list payload (GH #27).
    includeBody: options.bodyPreview !== undefined && options.bodyPreview > 0,
  });
}

/** Read stdin to completion as UTF-8, for `--stdin` item input. */
function readStdin(input: Readable = stdin): Promise<string> {
  return new Promise((resolvePromise, reject) => {
    let data = "";
    input.setEncoding("utf-8");
    input.on("data", (chunk) => {
      data += chunk;
    });
    input.on("end", () => resolvePromise(data));
    input.on("error", reject);
  });
}

function parseGroupBy(value: string): ChangelogGroupBy {
  if (value === "version" || value === "release" || value === "milestone") return value;
  throw new Error("--group-by must be 'version', 'release', or 'milestone'");
}

function parseSectionBy(value: string): ChangelogSectionBy {
  if (value === "category" || value === "type" || value === "status" || value === "label") return value;
  throw new Error("--section-by must be 'category', 'type', 'status', or 'label'");
}

/** Validate `--item-ref-style`, rejecting unknown spellings so a typo cannot
 * quietly change how every entry cites its item. */
function parseItemRefStyle(value: string): ChangelogItemRefStyle {
  const normalized = value.trim().toLowerCase();
  if (normalized === "auto" || normalized === "label" || normalized === "toon" || normalized === "github") {
    return normalized;
  }
  throw new Error("--item-ref-style must be 'auto', 'label', 'toon', or 'github'");
}

/** Validate `--limit` as a positive integer count of release sections. */
function parseLimit(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new Error("--limit must be a positive integer");
  }
  return parsed;
}

/** Validate `--body-preview` as a positive character width. */
function parseBodyPreview(value: string): number {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new Error("--body-preview must be a positive integer");
  }
  return parsed;
}

function parseMode(value: string): "replace" | "prepend" {
  if (value === "replace" || value === "prepend") return value;
  throw new Error("--mode must be 'replace' or 'prepend'");
}

/** Resolve the `--format` argument to the two shapes the generator emits.
 * Accepts `markdown` as an alias for `md` because the flag reads as prose and
 * the long spelling is the natural guess; case and surrounding whitespace are
 * normalized so a value copied from a shell script still matches. Anything else
 * throws rather than defaulting, so a typo cannot silently produce the wrong
 * output format in a release job. */
function parseFormat(value: string): "md" | "json" {
  const normalized = value.trim().toLowerCase();
  if (normalized === "md" || normalized === "markdown") return "md";
  if (normalized === "json") return "json";
  throw new Error("--format must be 'md' or 'json'");
}

/** Project parsed CLI options plus the loaded items onto the generator's option
 * shape. An empty `--exclude-tag` list is passed as `undefined` so the filter
 * stays entirely inert rather than running against nothing. */
function buildGenerationOptions(options: CliOptions, items: PmItem[]) {
  return {
    items,
    title: options.title,
    version: options.version,
    date: options.date,
    since: options.since,
    until: options.until,
    releaseWindows: options.releaseWindows,
    suppressedPendingRelease: options.suppressedPendingRelease,
    includeStatuses: options.statuses,
    groupBy: options.groupBy,
    sectionBy: options.sectionBy,
    conventional: options.conventional,
    contributors: options.contributors,
    limit: options.limit,
    sinceVersion: options.sinceVersion,
    breakingChanges: options.breakingChanges,
    bodyPreview: options.bodyPreview,
    emojiPrefix: options.emojiPrefix,
    includeMetadata: options.includeMetadata,
    suggestSemver: options.suggestSemver,
    includeEmpty: options.includeEmpty,
    includeLinks: options.includeLinks,
    itemUrlBase: options.itemUrlBase,
    itemRefStyle: options.itemRefStyle,
    respectItemRelease: options.respectItemRelease,
    excludeTags: options.excludeTags.length > 0 ? options.excludeTags : undefined,
  };
}

/** Assemble the machine-readable run summary emitted by `--json` and written as
 * GitHub step outputs. The job-summary panel receives generated markdown
 * instead, so it is not a consumer of this. */
function buildSummary(
  options: CliOptions,
  result: {
    output?: string;
    action: string;
    changed: boolean;
    markdown: string;
    itemCount: number;
    bytes: number;
  },
  output = result.output,
  selectionReport?: ChangelogSelectionReport
): Record<string, unknown> {
  const summary: Record<string, unknown> = {
    output,
    mode: options.mode,
    action: result.action,
    changed: result.changed,
    itemCount: result.itemCount,
    bytes: result.bytes,
    check: options.check,
    markdown: options.stdout ? result.markdown : undefined,
  };
  if (selectionReport) summary.selection_report = selectionReport;
  return summary;
}

/**
 * OPT-OUT (`--no-check-diff` suppresses): when `--check` fails, show WHAT
 * drifted, not just THAT it drifted.
 *
 * The failure line alone forces the reader - usually a CI agent that cannot
 * rerun the generator interactively - to clone the repo and diff generator
 * output by hand; the common cause (a PR branch behind `main`, so the merge ref
 * sees a release commit the branch lacks) is obvious from the diff in seconds.
 * Check mode never writes, so the file on disk is still the committed
 * changelog. Stderr only: stdout stays byte-identical for callers that capture
 * it.
 */
function writeCheckDiff(options: CliOptions, outputPath: string, generated: string): void {
  const committed = existsSync(outputPath) ? readFileSync(outputPath, "utf-8") : "";
  // Label with the output's basename (e.g. `CHANGELOG.md`) rather than the
  // resolved absolute path, so the side label stays short and recognizable
  // regardless of how the caller invoked --output.
  const oldLabel = `committed ${basename(options.output)}`;
  const diff = createUnifiedDiff(committed, generated, {
    oldLabel,
    newLabel: "generated",
  });
  process.stderr.write(diff.text);
  if (diff.truncated) {
    process.stderr.write(
      `... diff truncated: ${diff.omittedLines} more lines not shown (${DEFAULT_MAX_DIFF_LINES}-line cap).`
      + " Regenerate locally (rerun without --check, e.g. --mode replace) to see the full changelog.\n"
    );
  }
}

/** Print `--explain` diagnostics to stderr: how many items each filter stage
 * dropped, and how the survivors' release placement was dated. Stderr keeps
 * stdout byte-identical for callers capturing generated markdown. */
function writeSelectionReport(report: ChangelogSelectionReport): void {
  const excluded = report.excluded_counts;
  console.error(
    "Selection report:"
    + ` input=${report.stage_counts.input}`
    + ` visible=${report.stage_counts.visible_items}`
    + ` excluded(title=${excluded.missing_title},tag=${excluded.excluded_tag},status=${excluded.status},time=${excluded.time_window},item_release=${excluded.item_release},release_window=${excluded.release_window},visibility=${excluded.hidden_by_visibility})`
  );
  const provenance = report.attribution_provenance;
  if (provenance) {
    const sources = formatInferredSources(provenance.inferred_sources);
    console.error(
      `Attribution provenance: authoritative=${provenance.authoritative} inferred=${provenance.inferred}`
      + ` release_pinned=${provenance.release_pinned} (inferred sources: ${sources})`
    );
    if (provenance.inferred_sample.length > 0) {
      console.error(`Inferred-attribution sample: ${provenance.inferred_sample.join(", ")}`);
    }
  }
  for (const hint of report.hints) {
    console.error(`Hint: ${hint}`);
  }
}

/** Append the run summary as `key=value` step outputs for a workflow to branch
 * on, failing loudly when invoked outside GitHub Actions. */
function writeGitHubOutput(summary: Record<string, unknown>): void {
  const githubOutput = process.env.GITHUB_OUTPUT;
  if (!githubOutput) {
    throw new Error("--github-output requires the GITHUB_OUTPUT environment variable");
  }

  const lines = [
    `output=${String(summary.output ?? "")}`,
    `mode=${String(summary.mode ?? "")}`,
    `action=${String(summary.action ?? "")}`,
    `changed=${String(summary.changed ?? "")}`,
    `item_count=${String(summary.itemCount ?? "")}`,
    `bytes=${String(summary.bytes ?? "")}`,
  ];
  appendFileSync(githubOutput, `${lines.join("\n")}\n`, "utf-8");
}

/** Append generated markdown to the workflow's job summary panel, so release
 * notes are readable in the run without downloading an artifact. */
function writeGitHubStepSummary(markdown: string): void {
  const githubStepSummary = process.env.GITHUB_STEP_SUMMARY;
  if (!githubStepSummary) {
    throw new Error("--github-step-summary requires the GITHUB_STEP_SUMMARY environment variable");
  }

  appendFileSync(githubStepSummary, `${markdown.trimEnd()}\n`, "utf-8");
}

/** Read a flag's value, rejecting a missing one and a following `--flag`. The
 * latter catches an omitted value being silently swallowed by the next flag. */
function requireValue(args: string[], index: number, flag: string): string {
  const value = args[index];
  if (!value || value.startsWith("--")) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

/** Read a flag's value allowing a leading `--`, for flags whose argument may
 * legitimately look like one. */
function requireAnyValue(args: string[], index: number, flag: string): string {
  const value = args[index];
  if (!value) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

